const input = $input.first().json;
const cookies = JSON.stringify(input.cookies || []);
const localStorage = JSON.stringify(input.localStorage || {});
const lastUrl = input.url || 'https://app.cotadorsimplificado.com.br';

const code = `export default async function ({ page }) {
  const log = [];
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const cookies = ${cookies};
  const ls = ${localStorage};

  try {
    await page.setViewport({ width: 1280, height: 800 });
    log.push('Restaurando sessao...');
    await page.goto('${lastUrl}', { waitUntil: 'domcontentloaded', timeout: 30000 });
    if (cookies.length > 0) await page.setCookie(...cookies);
    await page.evaluate((ls) => {
      for (const [key, value] of Object.entries(ls)) {
        window.localStorage.setItem(key, value);
      }
    }, ls);
    await page.reload({ waitUntil: 'networkidle2' });
    await wait(2000);
    log.push('Sessao OK');

    log.push('Clicando PME...');
    const pme = await page.evaluateHandle(() => [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')));
    if (pme) await pme.click();
    await wait(3000);
    log.push('PME OK');

    log.push('Preenchendo nome...');
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    const nomeInput = await page.$('#id-nomelead');
    if (nomeInput) {
      await nomeInput.click();
      await wait(500);
      await nomeInput.type('teste', { delay: 50 });
    }
    log.push('Nome OK');

    log.push('Avancando 1...');
    const btnAv1 = await page.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan')));
    if (btnAv1) await btnAv1.click();
    await wait(3000);
    log.push('Avancar 1 OK');

    log.push('Preenchendo cidade...');
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    const cidadeInput = await page.$('#cidade_nome');
    if (cidadeInput) {
      await cidadeInput.click();
      await wait(500);
      await cidadeInput.type('recife', { delay: 50 });
    }
    await wait(2000);
    await page.keyboard.press('ArrowDown');
    await wait(500);
    await page.keyboard.press('Enter');
    await wait(2000);
    log.push('Cidade OK');

    log.push('Selecionando empresa...');
    const sel = await page.$('select');
    if (sel) {
      await sel.click();
      await wait(500);
      await page.select('select', 'MEI - EMPRESARIO INDIVIDUAL');
    }
    log.push('Empresa OK');

    log.push('Avancando 2...');
    const btnAv2 = await page.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan')));
    if (btnAv2) await btnAv2.click();
    await wait(3000);
    log.push('Avancar 2 OK');

    log.push('Preenchendo faixas...');
    const inputs = await page.$$('.bubble-rg input');
    let preenchidas = 0;
    for (let i = 0; i < Math.min(inputs.length, 10); i++) {
      try {
        await inputs[i].click();
        await inputs[i].type('1');
        preenchidas++;
        await wait(300);
      } catch(e) {}
    }
    log.push('Faixas: ' + preenchidas);

    const screenshot = await page.screenshot({ encoding: 'base64' });
    return { success: true, log, url: page.url(), screenshot };
  } catch (error) {
    const screenshot = await page.screenshot({ encoding: 'base64' }).catch(() => null);
    return { success: false, error: error.message, log, screenshot };
  }
}`;

return [{ json: { code } }];

const input = $input.first().json;
const success = input.success;
const error = input.error || 'Nenhum';
const log = (input.log || []).join('\n');
const url = input.url || '';

const texto = `*COTADOR HAPVIDA*

Status: ${success ? 'SUCESSO' : 'ERRO'}
Erro: ${error}

*Log de execucao:*
${log}

URL final: ${url}`;

return [{ json: { number: '5583999471031', text: texto } }];
